class LRU<K, V> {
    private map = new Map<K, V>()
    private cap: number
    constructor(cap: number) { this.cap = cap }
    get(k: K) { const v = this.map.get(k); if (v !== undefined) { this.map.delete(k); this.map.set(k, v) } return v }
    set(k: K, v: V) { this.map.delete(k); this.map.set(k, v); if (this.map.size > this.cap) this.map.delete(this.map.keys().next().value!) }
    keys() { return [...this.map.keys()] }
}
const lru = new LRU<string, number>(2)
lru.set("a", 1); lru.set("b", 2); lru.get("a"); lru.set("c", 3)
console.log(lru.keys())

class Emitter {
    private handlers: Record<string, ((...a: unknown[]) => void)[]> = {}
    on(e: string, fn: (...a: unknown[]) => void) { (this.handlers[e] ??= []).push(fn); return this }
    emit(e: string, ...args: unknown[]) { (this.handlers[e] ?? []).forEach(fn => fn(...args)) }
}
