class Inventory {
    private stock = new Map<string, number>()
    receive(item: string, qty: number) { this.stock.set(item, (this.stock.get(item) ?? 0) + qty) }
    ship(item: string, qty: number) {
        const have = this.stock.get(item) ?? 0
        if (qty > have) return `${item}: yetarli emas (${have} bor)`
        this.stock.set(item, have - qty)
        return `${item}: ${qty} ta jo'natildi`
    }
    report() { return Object.fromEntries(this.stock) }
}
const inv = new Inventory()
inv.receive("olma", 10); inv.receive("nok", 4)
console.log(inv.ship("olma", 3), "/", inv.ship("nok", 9))
console.log(inv.report())

