class PasswordManager {
    #passwords = new Map<string, string>()
    #masterKey: string

    constructor(masterKey: string) {
        this.#masterKey = masterKey
    }

    save(site: string, password: string): void {
        this.#passwords.set(site, this.#encrypt(password))
    }

    get(site: string): string | undefined {
        const encrypted = this.#passwords.get(site)
        return encrypted ? this.#decrypt(encrypted) : undefined
    }

    #encrypt(text: string): string {
        return [...text].map(c => String.fromCharCode(c.charCodeAt(0) + this.#masterKey.length)).join("")
    }

    #decrypt(text: string): string {
        return [...text].map(c => String.fromCharCode(c.charCodeAt(0) - this.#masterKey.length)).join("")
    }
}

