class Inventory {
    #items = new Map<string, number>()

    add(name: string, qty: number): this {
        this.#items.set(name, (this.#items.get(name) ?? 0) + qty)
        return this
    }

    remove(name: string, qty: number): boolean {
        const current = this.#items.get(name) ?? 0
        if (current < qty) return false
        this.#items.set(name, current - qty)
        return true
    }

    get snapshot(): ReadonlyMap<string, number> {
        return new Map(this.#items)
    }

    get totalItems(): number {
        return [...this.#items.values()].reduce((a, b) => a + b, 0)
    }
}

