class FileHandle implements Readable, Writable, Closable {
    private content = ""
    private isOpen = true

    read(): string {
        if (!this.isOpen) throw new Error("Fayl yopilgan")
        return this.content
    }

    write(data: string): void {
        if (!this.isOpen) throw new Error("Fayl yopilgan")
        this.content += data
    }

    close(): void {
        this.isOpen = false
    }
}

