interface Plugin {
    readonly name: string
    execute(input: string): string
}

class UppercasePlugin implements Plugin {
    readonly name = "uppercase"
    execute(input: string): string { return input.toUpperCase() }
}

class ReversePlugin implements Plugin {
    readonly name = "reverse"
    execute(input: string): string { return [...input].reverse().join("") }
}

class TrimPlugin implements Plugin {
    readonly name = "trim"
    execute(input: string): string { return input.trim() }
}

class Pipeline {
    private plugins: Plugin[] = []

    use(plugin: Plugin): this {
        this.plugins.push(plugin)
        return this
    }

    run(input: string): string {
        return this.plugins.reduce((value, plugin) => {
            const result = plugin.execute(value)
            console.log(`  ${plugin.name}: "${value}" → "${result}"`)
            return result
        }, input)
    }
}

const pipeline = new Pipeline().use(new TrimPlugin()).use(new UppercasePlugin()).use(new ReversePlugin())
console.log("Natija:", pipeline.run("  salom  "))

