interface DiscountStrategy { apply(total: number): number }

class NoDiscount implements DiscountStrategy { apply(t: number) { return t } }
class PercentDiscount implements DiscountStrategy {
    constructor(private percent: number) {}
    apply(t: number) { return t * (1 - this.percent / 100) }
}
class FixedDiscount implements DiscountStrategy {
    constructor(private amount: number) {}
    apply(t: number) { return Math.max(0, t - this.amount) }
}

const strategies: DiscountStrategy[] = [new NoDiscount(), new PercentDiscount(10), new FixedDiscount(50000)]
for (const s of strategies) console.log(s.constructor.name.padEnd(16), s.apply(300000))

