interface Repository<T> { add(x: T): void; all(): T[]; remove(pred: (x: T) => boolean): number }
class ArrayRepo<T> implements Repository<T> {
    private items: T[] = []
    add(x: T) { this.items.push(x) }
    all() { return [...this.items] }
    remove(pred: (x: T) => boolean) { const before = this.items.length; this.items = this.items.filter(x => !pred(x)); return before - this.items.length }
}
const r = new ArrayRepo<number>()
;[1, 2, 3, 4].forEach(n => r.add(n))
console.log(r.remove(n => n % 2 === 0), r.all())

interface SortStrategy { sort(a: number[]): number[] }
class Asc implements SortStrategy { sort(a: number[]) { return a.toSorted((x, y) => x - y) } }
class Desc implements SortStrategy { sort(a: number[]) { return a.toSorted((x, y) => y - x) } }
class Sorter {
    strategy: SortStrategy
    constructor(s: SortStrategy) { this.strategy = s }
    run(a: number[]) { return this.strategy.sort(a) }
}
const sorter = new Sorter(new Asc())
console.log(sorter.run([3, 1, 2]))
sorter.strategy = new Desc()
console.log(sorter.run([3, 1, 2]))

