class MathUtils {
    static readonly PI = 3.14159265359
    static readonly E = 2.71828182846

    static clamp(value: number, min: number, max: number): number {
        return Math.min(Math.max(value, min), max)
    }

    static lerp(start: number, end: number, t: number): number {
        return start + (end - start) * MathUtils.clamp(t, 0, 1)
    }

    static roundTo(value: number, digits: number): number {
        const factor = 10 ** digits
        return Math.round(value * factor) / factor
    }
}

console.log(MathUtils.clamp(150, 0, 100))
console.log(MathUtils.clamp(-10, 0, 100))
