class Order {
    private items: { name: string; price: number; qty: number }[] = []

    add(name: string, price: number, qty = 1): this {
        this.items.push({ name, price, qty })
        return this
    }

    get subtotal(): number {
        return this.items.reduce((sum, i) => sum + i.price * i.qty, 0)
    }

    get tax(): number {
        return Math.round(this.subtotal * 0.12)
    }

    get total(): number {
        return this.subtotal + this.tax
    }

    get itemCount(): number {
        return this.items.reduce((sum, i) => sum + i.qty, 0)
    }

    get summary(): string {
        return `${this.itemCount} ta mahsulot | ${this.subtotal} + soliq ${this.tax} = ${this.total}`
    }
}

