function timed<T extends (...args: any[]) => any>(target: T, context: ClassMethodDecoratorContext) {
    return function (this: any, ...args: any[]) {
        const start = Date.now()
        const result = target.apply(this, args)
        const duration = Date.now() - start
        console.log(`${String(context.name)}: ${duration >= 0 ? "bajarildi" : ""} (${typeof duration} qiymat)`)
        return result
    } as T
}

