function retry(attempts: number) {
    return function <T extends (...args: any[]) => any>(target: T, context: ClassMethodDecoratorContext) {
        return function (this: any, ...args: any[]) {
            let lastError: unknown
            for (let i = 1; i <= attempts; i++) {
                try {
                    const result = target.apply(this, args)
                    console.log(`${String(context.name)}: ${i}-urinishda muvaffaqiyat`)
                    return result
                } catch (e) {
                    lastError = e
                    console.log(`${String(context.name)}: ${i}-urinish muvaffaqiyatsiz`)
                }
            }
            throw lastError
        } as T
    }
}

