function debounce(ms: number) {
    return function (target: (...a: any[]) => void, _ctx: ClassMethodDecoratorContext) {
        let timer: ReturnType<typeof setTimeout> | undefined
        return function (this: any, ...a: any[]) { clearTimeout(timer); timer = setTimeout(() => target.apply(this, a), ms) }
    }
}
class Search { @debounce(10) query(q: string) { console.log("qidiruv:", q) } }
const sr = new Search()
sr.query("t"); sr.query("ty"); sr.query("typescript")
await new Promise(r => setTimeout(r, 30))

const requiredFields = new Map<string, string[]>()
function required(_: undefined, ctx: ClassFieldDecoratorContext) {
    ctx.addInitializer(function (this: any) {
        const cls = this.constructor.name
        const list = requiredFields.get(cls) ?? []
        if (!list.includes(String(ctx.name))) requiredFields.set(cls, [...list, String(ctx.name)])
    })
}
function validate(obj: any) { return (requiredFields.get(obj.constructor.name) ?? []).filter(f => !obj[f]) }
class SignupForm {
    @required email = ""
    @required password = "12345"
    nickname = ""
}
console.log("Bo'sh majburiy maydonlar:", validate(new SignupForm()))

function warnIfSlow(limit: number) {
    return function (target: (...a: any[]) => any, ctx: ClassMethodDecoratorContext) {
        return function (this: any, ...a: any[]) {
            const t = performance.now()
            const r = target.apply(this, a)
            if (performance.now() - t > limit) console.log(`⚠ ${String(ctx.name)} sekin ishladi`)
            return r
        }
    }
}
class Work {
    @warnIfSlow(1000) quick() { return "tez" }
}
console.log(new Work().quick())

