function trace(target: (...a: any[]) => any, ctx: ClassMethodDecoratorContext) {
    return function (this: any, ...a: any[]) { console.log(`static ${String(ctx.name)} chaqirildi`); return target.apply(this, a) }
}
class Util { @trace static sum(a: number, b: number) { return a + b } }
console.log(Util.sum(2, 3))

function observable<T>(target: ClassAccessorDecoratorTarget<any, T>, ctx: ClassAccessorDecoratorContext) {
    return {
        get(this: any) { return target.get.call(this) },
        set(this: any, v: T) { console.log(`${String(ctx.name)}: ${JSON.stringify(target.get.call(this))} → ${JSON.stringify(v)}`); target.set.call(this, v) },
    }
}
class Store { @observable accessor count = 0 }
const store = new Store()
store.count = 1
store.count = 5
console.log(store.count)

function nonEmpty(target: ClassAccessorDecoratorTarget<any, string>, ctx: ClassAccessorDecoratorContext) {
    return {
        set(this: any, v: string) { if (!v.trim()) throw new Error(`${String(ctx.name)} bo'sh bo'lmasin`); target.set.call(this, v) },
        get(this: any) { return target.get.call(this) },
    }
}
class Post { @nonEmpty accessor title = "Nomsiz" }
const post = new Post()
post.title = "Yangilik"
try { post.title = "   " } catch (e) { console.log((e as Error).message) }
console.log(post.title)

function deprecated(msg: string) {
    return function (target: (...a: any[]) => any, ctx: ClassMethodDecoratorContext) {
        let warned = false
        return function (this: any, ...a: any[]) {
            if (!warned) { console.log(`DEPRECATED ${String(ctx.name)}: ${msg}`); warned = true }
            return target.apply(this, a)
        }
    }
}
class OldApi { @deprecated("fetchV2 dan foydalaning") fetch() { return "v1" } }
const oa = new OldApi()
console.log(oa.fetch(), oa.fetch())

function frozen<T extends new (...a: any[]) => object>(Base: T, _ctx: ClassDecoratorContext) {
    return class extends Base { constructor(...a: any[]) { super(...a); Object.freeze(this) } }
}
@frozen class Point { x = 1; y = 2 }
const pt = new Point()
try { (pt as { x: number }).x = 9 } catch (e) { console.log((e as Error).constructor.name) }
console.log(pt.x)

const handlers: Record<string, string[]> = {}
function on(event: string) {
    return function (_t: unknown, ctx: ClassMethodDecoratorContext) {
        (handlers[event] ??= []).push(String(ctx.name))
    }
}
class Page {
    @on("click") handleClick() {}
    @on("click") trackClick() {}
    @on("scroll") lazyLoad() {}
}
console.log(handlers, typeof Page)

function memo(target: (n: number) => number, _ctx: ClassMethodDecoratorContext) {
    const cache = new Map<number, number>()
    return function (this: any, n: number) {
        if (!cache.has(n)) cache.set(n, target.call(this, n))
        return cache.get(n)!
    }
}
let computed = 0
class Calc { @memo square(n: number) { computed++; return n * n } }
const cl = new Calc()
console.log(cl.square(9), cl.square(9), cl.square(4), "hisoblandi:", computed)

function transactional(target: (...a: any[]) => any, ctx: ClassMethodDecoratorContext) {
    return function (this: any, ...a: any[]) {
        console.log("BEGIN")
        try { const r = target.apply(this, a); console.log("COMMIT"); return r }
        catch (e) { console.log("ROLLBACK:", (e as Error).message); return null }
    }
}
class Bank {
    @transactional transfer(amount: number) { if (amount > 1000) throw new Error("limit oshdi"); return `o'tkazildi ${amount}` }
}
console.log(new Bank().transfer(500))
console.log(new Bank().transfer(5000))

