function trimArgs(target: (...a: any[]) => any, _ctx: ClassMethodDecoratorContext) {
    return function (this: any, ...a: any[]) { return target.apply(this, a.map(x => (typeof x === "string" ? x.trim() : x))) }
}
class Registration {
    @trimArgs signup(name: string, email: string) { return `[${name}] [${email}]` }
}
console.log(new Registration().signup("  Ali ", " ali@mail.uz  "))
